from collections import defaultdict

def find_connected_components(grid):
    """Find all connected components of the same color, count cells per component."""
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                # BFS to find connected component
                color = grid[r][c]
                component = []
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    component.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                components.append((color, len(component), component))

    return components

# Find all connected components in the input
components = find_connected_components(demo_input)
for color, size, cells in components:
